function [ucost, ttake] = takeoff(ptake, ftake, materials)
    % Convert ptake to a numeric matrix
    ptakeNumeric = cell2mat(ptake);

    % Check if there are at least 2 months in ptake
    if size(ptakeNumeric, 1) < 2
        ttake = "Info is not enough";
        ucost = NaN;
        return
    end

    % Calculate unit costs
    % Extract quantities (all columns except last)
    quantities = ptakeNumeric(:, 1:end-1);
    % Extract total costs (last column)
    totalCosts = ptakeNumeric(:, end);

    % Compute unit costs
    ucost = sum(quantities) ./ sum(totalCosts);

    % Convert ftake to numeric matrix
    ftakeNumeric = cell2mat(ftake);

    % Calculate total cost for future months
    totalCost_ftake = ftakeNumeric(:, 1:end-1) * ucost';

    % Combine past and future quantities
    allQuantities = [ptakeNumeric(:, 1:end-1); ftakeNumeric(:, 1:end-1)];

    % Combine all data into ttake
    % Create a cell array for ttake
    ttake = [materials', num2cell(allQuantities, 2), num2cell([ptakeNumeric(:, end); totalCost_ftake], 2)];

    % Add the "cost" row
    ttake = [ttake; "cost", "", "", "", num2cell([sum(ptakeNumeric(:, end)), sum(totalCost_ftake)])];
end
