// Интерфейс посредника
public interface IMediator
{
    void PlaceOrder(string userId, string productId);
    void CancelOrder(string orderId);
}

// Класс посредника
public class OrderMediator : IMediator
{
    private List<string> orders = new List<string>();
    private Dictionary<string, string> userProducts = new Dictionary<string, string>();

    public void PlaceOrder(string userId, string productId)
    {
        string orderId = Guid.NewGuid().ToString();
        orders.Add(orderId);
        userProducts[orderId] = userId + " - " + productId;
        Console.WriteLine($"Order {orderId} placed for user {userId} and product {productId}");
    }

    public void CancelOrder(string orderId)
    {
        if (orders.Contains(orderId))
        {
            orders.Remove(orderId);
            userProducts.Remove(orderId);
            Console.WriteLine($"Order {orderId} canceled");
        }
        else
        {
            Console.WriteLine($"Order {orderId} not found");
        }
    }
}

